502	    let stdout_handle = child.stdout.take().expect("stdout was piped");
503	    let stderr_handle = child.stderr.take().expect("stderr was piped");
504	
505	    // The reader threads signal completion over a channel rather than
506	    // being joined directly. Killing (or the natural exit of) the
507	    // direct child does NOT close pipe fds held open by a descendant
508	    // process that inherited them (common for npm/cargo/python publish
509	    // lifecycle scripts spawning subprocesses). If that happens, the
510	    // blocking `read()` inside these threads never returns. Using
511	    // `recv_timeout` below lets us bound how long we wait for them
