/// Captured `CommandOutput` is identical either way; this only affects what the terminal shows while it runs.
#[derive(Clone, Copy, PartialEq, Eq)]
struct LiveEcho {
    stdout: bool,
    stderr: bool,
}

impl LiveEcho {
    const NONE: Self = Self {
        stdout: false,
        stderr: false,
    };
    const STDERR: Self = Self {
        stdout: false,
        stderr: true,
    };
    /// A publish: pnpm prints its errors to stdout, so both streams are shown.
    const BOTH: Self = Self {
        stdout: true,
        stderr: true,
    };
}

/// Drains `reader` to its end and returns what it said, keeping at most [`MAX_CAPTURED_OUTPUT_BYTES`]; the rest is
/// read and dropped so the child never blocks on a full pipe.
///
/// With `echo`, each line is also written to this process's stderr with `secrets` redacted first (registry tools can
/// echo a credential verbatim). The returned text stays raw so classifiers keep matching exact upstream text. Lines
/// are read as bytes: a line iterator has no bound on a single line, so a flood with no newlines would buffer without
/// limit before it could be capped.
fn capture_stream(mut reader: impl Read, echo: bool, secrets: &[String]) -> String {
    let mut captured: Vec<u8> = Vec::new();
    let mut truncated = false;
    let mut pending_line: Vec<u8> = Vec::new();
    let mut chunk = [0u8; 65536];
    let echo_line = |line: &mut Vec<u8>| {
        if line.last() == Some(&b'\r') {
            line.pop();
        }
        eprintln!("{}", redact_known_secrets(&String::from_utf8_lossy(line), secrets));
    };
    loop {
        match reader.read(&mut chunk) {
            Ok(0) | Err(_) => break,
            Ok(n) => {
                let data = &chunk[..n];
                if echo {
                    for &b in data {
                        if b == b'\n' {
                            echo_line(&mut pending_line);
                            pending_line.clear();
                        } else if pending_line.len() < MAX_CAPTURED_OUTPUT_BYTES {
                            pending_line.push(b);
                        }
                    }
                }
                if !truncated {
                    let take = data.len().min(MAX_CAPTURED_OUTPUT_BYTES - captured.len());
                    captured.extend_from_slice(&data[..take]);
                    truncated = take < data.len();
                }
            }
        }
    }
    if echo && !pending_line.is_empty() {
        echo_line(&mut pending_line);
    }
    let mut text = String::from_utf8_lossy(&captured).into_owned();
    if truncated {
        text.push_str("\n...[output truncated]\n");
    }
    text
}

/// `live_secrets`: known-credential values (see
/// [`callisto_model::known_credential_env_values`]) to redact from each
/// line *before* it's echoed live to the terminal via `eprintln!`. This is
/// deliberately separate from -- and does not affect -- the `captured`
/// buffer that becomes the returned `CommandOutput.stderr`: that copy must
/// stay byte-for-byte raw so downstream classifiers (e.g.
/// `extract_retry_after_duration`, `detect_auth_failure`) can still match
/// exact upstream text. Callers pass the secrets list in rather than this
/// function reading the environment itself, keeping it pure and testable
/// with a synthetic list.
fn run_with_timeout_impl(
    program: &str,
    args: &[&str],
    cwd: &Path,
    timeout: Duration,
    echo: LiveEcho,
    live_secrets: Vec<String>,
    child_env: ChildEnvironment<'_>,
) -> Result<CommandOutput, CommandError> {
    let mut command = std::process::Command::new(program);
    command
        .args(args)
        .current_dir(cwd)
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
    for name in child_env.remove {
        command.env_remove(name);
    }
    for (name, value) in child_env.set {
        command.env(name, value);
    }
    remove_unrelated_cargo_registry_tokens(&mut command, program);
    let mut child = command.spawn().map_err(|e| {
        if e.kind() == std::io::ErrorKind::NotFound {
            CommandError::NotFound {
                program: program.to_string(),
            }
        } else {
            CommandError::Io {
                program: program.to_string(),
                message: e.to_string(),
            }
        }
    })?;

    // Read stdout/stderr in separate threads to prevent pipe-buffer deadlock
    // when the child produces output while we wait for it to exit.
    let stdout_handle = child.stdout.take().expect("stdout was piped");
    let stderr_handle = child.stderr.take().expect("stderr was piped");

    // The reader threads signal completion over a channel rather than
    // being joined directly. Killing (or the natural exit of) the
    // direct child does NOT close pipe fds held open by a descendant
    // process that inherited them (common for npm/cargo/python publish
    // lifecycle scripts spawning subprocesses). If that happens, the
    // blocking `read()` inside these threads never returns. Using
    // `recv_timeout` below lets us bound how long we wait for them
    // without ever blocking the caller indefinitely.
    let (stdout_tx, stdout_rx) = std::sync::mpsc::channel::<String>();
    let (stderr_tx, stderr_rx) = std::sync::mpsc::channel::<String>();

    let stdout_secrets = live_secrets.clone();
    std::thread::spawn(move || {
        drop(stdout_tx.send(capture_stream(stdout_handle, echo.stdout, &stdout_secrets)));
    });
    // Stderr streams line by line so publish progress (cargo/npm/twine write to stderr) appears in real time rather
    // than after the process exits. `echo` gates only the live printing; captured output is identical either way.
    std::thread::spawn(move || {
        drop(stderr_tx.send(capture_stream(stderr_handle, echo.stderr, &live_secrets)));
    });

    // Grace period to wait for the reader threads after the direct
    // child has exited (or been killed). Bounded so a lingering
    // descendant holding the pipe open can never hang the caller.
    const READER_GRACE: Duration = Duration::from_secs(3);

    let deadline = Instant::now() + timeout;
    let status = loop {
        match child.try_wait().map_err(|e| CommandError::Io {
            program: program.to_string(),
            message: e.to_string(),
        })? {
            Some(s) => break s,
            None => {
                if Instant::now() >= deadline {
                    drop(child.kill());
                    drop(child.wait());
                    // Reader threads are intentionally not joined here:
                    // if a descendant process is still holding a pipe
                    // fd open, join() could block forever. We wait a
                    // bounded grace period for output, then abandon the
                    // threads (they leak until the descendant
                    // eventually exits and closes the fd -- a thread
                    // leak, not a memory-safety issue).
                    let stdout = stdout_rx.recv_timeout(READER_GRACE).ok();
                    let stderr = stderr_rx.recv_timeout(READER_GRACE).ok();
                    if stdout.is_none() || stderr.is_none() {
                        eprintln!(
                            "warning: `{program}` timed out and a descendant process \
                                 appears to still hold its output pipes open; captured \
                                 output may be incomplete"
                        );
                    }
                    return Err(CommandError::TimedOut {
                        program: program.to_string(),
                        seconds: timeout.as_secs(),
                    });
                }
                std::thread::sleep(Duration::from_millis(50));
            }
        }
    };

    // The direct child has exited on its own. Even so, a descendant
    // process can still hold the pipe fds open (e.g. a backgrounded
    // job spawned by a shell script), so bound the wait here too.
    let stdout_result = stdout_rx.recv_timeout(READER_GRACE);
    let stderr_result = stderr_rx.recv_timeout(READER_GRACE);
    // Incomplete output with a clean exit would read as an empty success to every classifier.
    let (Ok(stdout), Ok(stderr)) = (stdout_result, stderr_result) else {
        return Err(CommandError::Io {
            program: program.to_string(),
            message:
                "it exited but a descendant process still holds its output pipes open, so its output is incomplete"
                    .to_string(),
        });
    };

    note_failed_command(program, status.code(), &stderr);
    Ok(CommandOutput {
        exit_code: status.code(),
        stdout,
        stderr,
    })
}

