403	/// Drains `reader` to its end and returns what it said, keeping at most [`MAX_CAPTURED_OUTPUT_BYTES`]; the rest is
404	/// read and dropped so the child never blocks on a full pipe.
405	///
406	/// With `echo`, each line is also written to this process's stderr with `secrets` redacted first (registry tools can
407	/// echo a credential verbatim). The returned text stays raw so classifiers keep matching exact upstream text. Lines
408	/// are read as bytes: a line iterator has no bound on a single line, so a flood with no newlines would buffer without
409	/// limit before it could be capped.
410	fn capture_stream(mut reader: impl Read, echo: bool, secrets: &[String]) -> String {
411	    let mut captured: Vec<u8> = Vec::new();
412	    let mut truncated = false;
413	    let mut pending_line: Vec<u8> = Vec::new();
414	    let mut chunk = [0u8; 65536];
415	    let echo_line = |line: &mut Vec<u8>| {
416	        if line.last() == Some(&b'\r') {
417	            line.pop();
418	        }
419	        eprintln!("{}", redact_known_secrets(&String::from_utf8_lossy(line), secrets));
420	    };
421	    loop {
422	        match reader.read(&mut chunk) {
423	            Ok(0) | Err(_) => break,
424	            Ok(n) => {
425	                let data = &chunk[..n];
426	                if echo {
427	                    for &b in data {
428	                        if b == b'\n' {
429	                            echo_line(&mut pending_line);
430	                            pending_line.clear();
431	                        } else if pending_line.len() < MAX_CAPTURED_OUTPUT_BYTES {
432	                            pending_line.push(b);
433	                        }
434	                    }
435	                }
436	                if !truncated {
437	                    let take = data.len().min(MAX_CAPTURED_OUTPUT_BYTES - captured.len());
438	                    captured.extend_from_slice(&data[..take]);
439	                    truncated = take < data.len();
440	                }
441	            }
442	        }
443	    }
444	    if echo && !pending_line.is_empty() {
445	        echo_line(&mut pending_line);
446	    }
447	    let mut text = String::from_utf8_lossy(&captured).into_owned();
448	    if truncated {
449	        text.push_str("\n...[output truncated]\n");
450	    }
451	    text
452	}
