464	fn run_with_timeout_impl(
465	    program: &str,
466	    args: &[&str],
467	    cwd: &Path,
468	    timeout: Duration,
469	    echo: LiveEcho,
470	    live_secrets: Vec<String>,
471	    child_env: ChildEnvironment<'_>,
472	) -> Result<CommandOutput, CommandError> {
473	    let mut command = std::process::Command::new(program);
474	    command
475	        .args(args)
476	        .current_dir(cwd)
477	        .stdin(Stdio::null())
478	        .stdout(Stdio::piped())
479	        .stderr(Stdio::piped());
480	    for name in child_env.remove {
481	        command.env_remove(name);
482	    }
483	    for (name, value) in child_env.set {
484	        command.env(name, value);
485	    }
486	    remove_unrelated_cargo_registry_tokens(&mut command, program);
487	    let mut child = command.spawn().map_err(|e| {
488	        if e.kind() == std::io::ErrorKind::NotFound {
489	            CommandError::NotFound {
490	                program: program.to_string(),
491	            }
492	        } else {
493	            CommandError::Io {
494	                program: program.to_string(),
495	                message: e.to_string(),
496	            }
497	        }
498	    })?;
499	
500	    // Read stdout/stderr in separate threads to prevent pipe-buffer deadlock
501	    // when the child produces output while we wait for it to exit.
502	    let stdout_handle = child.stdout.take().expect("stdout was piped");
503	    let stderr_handle = child.stderr.take().expect("stderr was piped");
504	
505	    // The reader threads signal completion over a channel rather than
506	    // being joined directly. Killing (or the natural exit of) the
507	    // direct child does NOT close pipe fds held open by a descendant
508	    // process that inherited them (common for npm/cargo/python publish
509	    // lifecycle scripts spawning subprocesses). If that happens, the
510	    // blocking `read()` inside these threads never returns. Using
511	    // `recv_timeout` below lets us bound how long we wait for them
512	    // without ever blocking the caller indefinitely.
513	    let (stdout_tx, stdout_rx) = std::sync::mpsc::channel::<String>();
514	    let (stderr_tx, stderr_rx) = std::sync::mpsc::channel::<String>();
515	
516	    let stdout_secrets = live_secrets.clone();
517	    std::thread::spawn(move || {
518	        drop(stdout_tx.send(capture_stream(stdout_handle, echo.stdout, &stdout_secrets)));
519	    });
520	    // Stderr streams line by line so publish progress (cargo/npm/twine write to stderr) appears in real time rather
521	    // than after the process exits. `echo` gates only the live printing; captured output is identical either way.
522	    std::thread::spawn(move || {
523	        drop(stderr_tx.send(capture_stream(stderr_handle, echo.stderr, &live_secrets)));
524	    });
525	
526	    // Grace period to wait for the reader threads after the direct
527	    // child has exited (or been killed). Bounded so a lingering
528	    // descendant holding the pipe open can never hang the caller.
529	    const READER_GRACE: Duration = Duration::from_secs(3);
530	
531	    let deadline = Instant::now() + timeout;
532	    let status = loop {
533	        match child.try_wait().map_err(|e| CommandError::Io {
534	            program: program.to_string(),
535	            message: e.to_string(),
536	        })? {
537	            Some(s) => break s,
538	            None => {
539	                if Instant::now() >= deadline {
540	                    drop(child.kill());
541	                    drop(child.wait());
542	                    // Reader threads are intentionally not joined here:
543	                    // if a descendant process is still holding a pipe
544	                    // fd open, join() could block forever. We wait a
545	                    // bounded grace period for output, then abandon the
546	                    // threads (they leak until the descendant
547	                    // eventually exits and closes the fd -- a thread
548	                    // leak, not a memory-safety issue).
549	                    let stdout = stdout_rx.recv_timeout(READER_GRACE).ok();
550	                    let stderr = stderr_rx.recv_timeout(READER_GRACE).ok();
551	                    if stdout.is_none() || stderr.is_none() {
552	                        eprintln!(
553	                            "warning: `{program}` timed out and a descendant process \
554	                                 appears to still hold its output pipes open; captured \
555	                                 output may be incomplete"
556	                        );
557	                    }
558	                    return Err(CommandError::TimedOut {
559	                        program: program.to_string(),
560	                        seconds: timeout.as_secs(),
561	                    });
562	                }
563	                std::thread::sleep(Duration::from_millis(50));
564	            }
565	        }
566	    };
