574	    let (Ok(stdout), Ok(stderr)) = (stdout_result, stderr_result) else {
575	        return Err(CommandError::Io {
576	            program: program.to_string(),
577	            message:
578	                "it exited but a descendant process still holds its output pipes open, so its output is incomplete"
579	                    .to_string(),
580	        });
581	    };
582	
583	    note_failed_command(program, status.code(), &stderr);
