65	fn collect(root: &Path, dir: &Path, entries: &mut BTreeMap<PathBuf, u64>) {
66	    let Ok(read_dir) = std::fs::read_dir(dir) else {
67	        return;
68	    };
69	    for entry in read_dir.flatten() {
70	        let path = entry.path();
71	        match entry.file_type() {
72	            Ok(ft) if ft.is_dir() => collect(root, &path, entries),
73	            Ok(ft) if ft.is_file() => {
74	                let Ok(bytes) = std::fs::read(&path) else {
75	                    continue;
76	                };
77	                let mut hasher = DefaultHasher::new();
78	                bytes.hash(&mut hasher);
79	                let rel = path.strip_prefix(root).unwrap_or(&path).to_path_buf();
80	                let rel_str = rel.to_string_lossy();
81	                // Background git maintenance writes `.git/objects` and `.git/info`; refs and index still catch real writes.
82	                if (rel_str.contains(".git/") && rel_str.ends_with(".lock"))
83	                    || rel_str.contains(".git/objects/")
84	                    || rel_str.contains(".git/info/")
85	                {
86	                    continue;
87	                }
88	                let _prev = entries.insert(rel, hasher.finish());
89	            }

